. (Join-Path $PSScriptRoot 'cloud-common.ps1')
$infoPath=Join-Path $ProjectRoot 'dist\alb-deployment.json';if(-not(Test-Path -LiteralPath $infoPath)){throw 'Run npm run alb:deploy first.'};$origin=(Get-Content -LiteralPath $infoPath -Raw|ConvertFrom-Json).url.TrimEnd('/')
foreach($name in 'cml-vehicles','cml-fuel','cml-reminders'){$config=Invoke-Aws lambda get-function-configuration --function-name $name|ConvertFrom-Json;$variables=@{};$config.Environment.Variables.psobject.Properties|ForEach-Object{$variables[$_.Name]=$_.Value};$origins=@($variables.CORS_ORIGINS.Split(',')|ForEach-Object{$_.Trim()}|Where-Object{$_});if($origins -notcontains $origin){$variables.CORS_ORIGINS=(@($origins)+$origin)-join ','};$path=Join-Path $ProjectRoot "dist\$name-alb-cors.json";Write-JsonFile $path @{Variables=$variables};Invoke-Aws lambda update-function-configuration --function-name $name --environment "file://$path"|Out-Null;Write-Host "Updated exact-origin CORS for $name"}
